"""odl_mq.py — OdinLink stream transport for vLLM MessageQueue remote readers.

Replaces the zmq XPUB/SUB *data plane* of vllm's shm_broadcast.MessageQueue
for cross-box readers with the odl_tb5 stream API (same kernel driver and
userspace lib the odl_ar2 all-reduce and the RCCL net plugin ride). The zmq
sockets stay for the init-time subscribe/READY handshake.

Why: the per-step input broadcast (EngineCore box1 -> TP1 worker box2) and
the TP1 worker's response queue cross thunderbolt-net TCP, and a couple of
those traversals block each decode step. Riding the OdinLink streams removes
the per-step TCP dependency and its latency sensitivity.

Rendezvous (per MessageQueue, single remote reader):
  1. Writer opens a kernel-auto-assigned stream (sid W, IDA range 20-255,
     collision-free per host) and advertises W in the Handle (odl_mq_hello).
  2. Reader (cross-box only — a same-box "remote" reader, e.g. TP0's
     response queue read by the same-host EngineCore, declines and stays on
     zmq): opens its own auto-assigned stream (sid R) and sends a 4-byte
     hello [R] to dst W, BEFORE its zmq subscribe.
  3. Writer, in wait_until_ready after the zmq subscription arrived (which
     the reader only sends after the hello), waits briefly for the hello on
     W. Hello -> data plane = odl frames to dst R. Timeout -> reader
     declined -> zmq data plane as stock.

Framing (mirrors odl_pingpong/odl_stress): 4-byte little-endian total-length
frame, then the payload blob in <=4000-byte frames. Blob = [2B buffer count]
[4B len][buf]... so pickle out-of-band buffers survive like send_multipart.

Env:
  DS4_ODL_MQ=1          gate, read by shm_broadcast.py (not here)
  ODL_MQ_DEV            odl device index (default 0)
  ODL_MQ_LIB            explicit path to libodl_tb5.so.0
"""
import ctypes
import os
import pickle
import socket
import struct
import threading

_CHUNK = 4000  # single-frame payload cap, matches the frame pool (4096B frames)

DEV = int(os.environ.get("ODL_MQ_DEV", "0"))
_WAIT_PEER_MS = int(os.environ.get("ODL_MQ_WAIT_PEER_MS", "15000"))
_HELLO_MAGIC = 0xD54D

_LIB_CANDIDATES = [
    os.environ.get("ODL_MQ_LIB", ""),
    os.path.join(os.path.dirname(os.path.abspath(__file__)), "libodl_tb5.so.0"),
    os.path.expanduser("~/.cache/odinlink/build/lib/libodl_tb5.so.0"),
    "/var/home/alex/.cache/odinlink/build/lib/libodl_tb5.so.0",
    "libodl_tb5.so.0",
]

_lib = None
_lib_lock = threading.Lock()


def is_local_ip(ip: str) -> bool:
    """True iff `ip` is bound to an interface on THIS host (UDP-bind test)."""
    ip = ip.strip("[]")
    fam = socket.AF_INET6 if ":" in ip else socket.AF_INET
    s = socket.socket(fam, socket.SOCK_DGRAM)
    try:
        s.bind((ip, 0))
        return True
    except OSError:
        return False
    finally:
        s.close()


def _load():
    global _lib
    with _lib_lock:
        if _lib is not None:
            return _lib
        last = None
        for p in _LIB_CANDIDATES:
            if not p:
                continue
            try:
                lib = ctypes.CDLL(p)
            except OSError as e:
                last = e
                continue
            lib.odl_tb5_open.argtypes = [ctypes.POINTER(ctypes.c_void_p), ctypes.c_int]
            lib.odl_tb5_open.restype = ctypes.c_int
            lib.odl_tb5_close.argtypes = [ctypes.c_void_p]
            lib.odl_tb5_wait_peer.argtypes = [ctypes.c_void_p, ctypes.c_int]
            lib.odl_tb5_wait_peer.restype = ctypes.c_int
            lib.odl_tb5_stream_open.argtypes = [
                ctypes.c_void_p, ctypes.c_uint8, ctypes.POINTER(ctypes.c_uint8)]
            lib.odl_tb5_stream_open.restype = ctypes.c_int
            lib.odl_tb5_stream_close.argtypes = [ctypes.c_void_p, ctypes.c_uint8]
            lib.odl_tb5_stream_send.argtypes = [
                ctypes.c_void_p, ctypes.c_uint8, ctypes.c_uint8,
                ctypes.c_void_p, ctypes.c_uint32]
            lib.odl_tb5_stream_send.restype = ctypes.c_int
            lib.odl_tb5_stream_recv.argtypes = [
                ctypes.c_void_p, ctypes.c_uint8, ctypes.c_void_p, ctypes.c_uint32,
                ctypes.POINTER(ctypes.c_uint8), ctypes.POINTER(ctypes.c_uint32)]
            lib.odl_tb5_stream_recv.restype = ctypes.c_int
            lib.odl_tb5_stream_wait_rx.argtypes = [
                ctypes.c_void_p, ctypes.c_uint8, ctypes.c_uint32]
            lib.odl_tb5_stream_wait_rx.restype = ctypes.c_int
            _lib = lib
            return lib
        raise RuntimeError(f"libodl_tb5.so.0 not found ({last})")


class _Endpoint:
    """Device handle + one kernel-auto-assigned stream."""

    def __init__(self):
        lib = _load()
        h = ctypes.c_void_p()
        rc = lib.odl_tb5_open(ctypes.byref(h), DEV)
        if rc < 0:
            raise RuntimeError(f"odl_tb5_open({DEV}) failed: {rc}")
        rc = lib.odl_tb5_wait_peer(h, _WAIT_PEER_MS)
        if rc < 0:
            lib.odl_tb5_close(h)
            raise RuntimeError(f"odl_tb5_wait_peer failed: {rc}")
        sid = ctypes.c_uint8()
        rc = lib.odl_tb5_stream_open(h, 0, ctypes.byref(sid))
        if rc < 0:
            lib.odl_tb5_close(h)
            raise RuntimeError(f"odl_tb5_stream_open(auto) failed: {rc}")
        self._lib = lib
        self._h = h
        self.sid = sid.value
        self._lock = threading.Lock()

    def close(self):
        h, self._h = self._h, None
        if h:
            self._lib.odl_tb5_stream_close(h, self.sid)
            self._lib.odl_tb5_close(h)

    def __del__(self):
        try:
            self.close()
        except Exception:
            pass

    def _wait_rx(self, timeout_ms: int) -> bool:
        """True if data is waiting on our stream, False on timeout."""
        rc = self._lib.odl_tb5_stream_wait_rx(self._h, self.sid, timeout_ms)
        if rc in (-110, -11, -62):  # ETIMEDOUT / EAGAIN / ETIME
            return False
        if rc < 0:
            raise RuntimeError(f"odl_mq wait_rx failed: {rc}")
        return True

    def _recv_exact(self, want: int) -> bytes:
        lib, h, sid = self._lib, self._h, self.sid
        out = bytearray(want)
        got = 0
        src = ctypes.c_uint8()
        actual = ctypes.c_uint32()
        tmp = (ctypes.c_char * _CHUNK)()
        while got < want:
            n = min(_CHUNK, want - got)
            rc = lib.odl_tb5_stream_recv(
                h, sid, tmp, n, ctypes.byref(src), ctypes.byref(actual))
            if rc < 0:
                raise RuntimeError(f"odl_mq recv failed: {rc}")
            a = actual.value
            if a == 0:
                raise RuntimeError("odl_mq: zero-length frame")
            out[got:got + a] = tmp.raw[:a]
            got += a
        return bytes(out)

    def _send(self, dst: int, data: bytes) -> None:
        lib, h, sid = self._lib, self._h, self.sid
        rc = lib.odl_tb5_stream_send(h, sid, dst, data, len(data))
        if rc < 0:
            raise RuntimeError(f"odl_mq send failed: {rc}")


class Writer(_Endpoint):
    """Data-plane sender. Advertise `hello_sid` via Handle.odl_mq_hello; call
    wait_hello() from wait_until_ready after the reader's zmq subscription
    arrived; send_multipart is valid only once wait_hello returned True."""

    def __init__(self):
        super().__init__()
        self.dst = None

    @property
    def hello_sid(self) -> int:
        return self.sid

    def wait_hello(self, timeout_ms: int = 3000) -> bool:
        with self._lock:
            if not self._wait_rx(timeout_ms):
                return False
            magic, r = struct.unpack("<HH", self._recv_exact(4))
        if magic != _HELLO_MAGIC:
            raise RuntimeError(f"odl_mq: bad hello magic {magic:#x}")
        self.dst = r
        return True

    def send_multipart(self, buffers) -> None:
        dst = self.dst
        if dst is None:
            raise RuntimeError("odl_mq: send before hello (wait_until_ready)")
        parts = [struct.pack("<H", len(buffers))]
        for b in buffers:
            raw = b if isinstance(b, (bytes, bytearray)) else bytes(b)
            parts.append(struct.pack("<I", len(raw)))
            parts.append(raw)
        blob = b"".join(parts)
        with self._lock:
            self._send(dst, struct.pack("<I", len(blob)))
            off, total = 0, len(blob)
            while off < total:
                n = min(_CHUNK, total - off)
                self._send(dst, (ctypes.c_char * n).from_buffer_copy(blob, off))
                off += n


class Reader(_Endpoint):
    """Data-plane receiver. Opens an auto-assigned stream and hellos the
    writer's stream with our sid — call BEFORE the zmq subscribe so the
    writer's wait_hello (gated on the subscription) always finds it."""

    def __init__(self, hello_dst: int):
        super().__init__()
        self._send(hello_dst, struct.pack("<HH", _HELLO_MAGIC, self.sid))

    def recv(self, timeout: float | None):
        """Mirror MessageQueue.recv(socket, timeout): returns the unpickled
        object, raises TimeoutError if no message within timeout seconds."""
        with self._lock:
            if timeout is not None and not self._wait_rx(int(timeout * 1000)):
                raise TimeoutError
            (total,) = struct.unpack("<I", self._recv_exact(4))
            blob = self._recv_exact(total)
        (count,) = struct.unpack_from("<H", blob, 0)
        offset = 2
        bufs = []
        view = memoryview(blob)
        for _ in range(count):
            (blen,) = struct.unpack_from("<I", blob, offset)
            offset += 4
            bufs.append(view[offset:offset + blen])
            offset += blen
        return pickle.loads(bufs[0], buffers=bufs[1:])
